questiontext.text:
Answer: [[input:ans1]] [[validation:ans1]] [[feedback:prt1]]

<h3 style="text-align:center;">
Plane and point in \(\mathbb{R}^3\)
</h3>

<p style="text-align:center;">
A shaded plane and a point \(P={@P@}\) are shown below.
</p>

[[jsxgraph width="600px" height="420px"]]
  var L = 4;

  var board = JXG.JSXGraph.initBoard(divid, {
    boundingbox: [-6,6,6,-6],
    axis: false,
    showNavigation: true
  });

  /* REQUIRED invisible 2D anchor */
  board.create('point', [0,0], {visible:false});

  /* 3D view */
  var view = board.create('view3d',
    [[-6,-6],[12,12],[[-L,L],[-L,L],[-L,L]]]
  );

  view.create('axes3d', []);

  /* Tilted plane as a shaded quadrilateral */
  var A = view.create('point3d', [-L,-L,  1], {visible:false});
  var B = view.create('point3d', [ L,-L, -1], {visible:false});
  var C = view.create('point3d', [ L, L,  0], {visible:false});
  var D = view.create('point3d', [-L, L,  2], {visible:false});

  view.create('polygon3d', [A,B,C,D], {
    fillOpacity: 0.4,
    borders: {strokeWidth: 1}
  });

  /* Point P */
  view.create('point3d', [{#px#},{#py#},{#pz#}], {
    name: 'P',
    size: 5,
    fixed: true
  });
[[/jsxgraph]]

questionvariables.text:
/* Size of the 3D box */
L: 4;

/* Coordinates of the point */
px: 1;
py: -1;
pz: 2;

P: ntuple(px,py,pz);
